    function openCipoV168(j){const cm=cipoMetrics(j),byCategory=new Map();for(const row of cm.details){const key=row.category||row.description||'Outros',value=num(row.source_paid??row.ledger_amount??row.delta)||0;byCategory.set(key,(byCategory.get(key)||0)+value)}const groups=[...byCategory].map(([name,total])=>({name,total})).sort((a,b)=>b.total-a.total);return modal('CIPÓ 396 · compra e obra','Compra, melhorias e financiamento exibidos em camadas separadas.','<div class="v168-kpis">'+kpi('Compra paga',cm.purchase,'base histórica','primary')+kpi('Obra e reforma',cm.works,cm.details.length+' itens detalhados')+kpi('Saldo para quitação',j.cipo_detail?.current_payoff_brl,'posição documental')+kpi('Até o vencimento',j.cipo_detail?.contractual_outflow_current_terms_brl,'termos atuais · sujeito à TR')+'</div><div class="v168-grid equal" style="margin-top:12px"><article class="v168-card"><div class="v168-cardhead"><div><span>Obra</span><h2>Gastos por grupo</h2></div></div>'+rankRows(groups,30)+'</article><article class="v168-card"><div class="v168-cardhead"><div><span>Financiamento</span><h2>Quitar agora × seguir contrato</h2></div></div><div class="v168-statlist"><div class="v168-stat"><span>Saldo para quitação</span><b>'+money(j.cipo_detail?.current_payoff_brl)+'</b></div><div class="v168-stat"><span>Pagamentos futuros nos termos atuais</span><b>'+money(j.cipo_detail?.contractual_outflow_current_terms_brl)+'</b></div></div><div class="v168-note warn">A comparação contratual pode mudar com a TR; não é tratada como valor fixo.</div></article></div><div class="v168-tablewrap" style="margin-top:12px"><table class="v168-table"><thead><tr><th>Item da obra</th><th>Grupo</th><th>Origem</th><th class="num">Valor</th></tr></thead><tbody>'+(cm.details.map(x=>'<tr><td>'+esc(x.description||'Item')+'</td><td>'+esc(x.category||'Outros')+'</td><td>'+esc(x.origin||'Planilha de obra')+'</td><td class="num">'+money(x.source_paid??x.ledger_amount??x.delta)+'</td></tr>').join('')||'<tr><td colspan="4">O detalhamento da obra ainda não está disponível neste leitor.</td></tr>')+'</tbody></table></div>')}
    function patrimonioV168Final(){ensureWealth();const s=st.wealth,j=s.data||{},body=s.loading&&!s.data?loading():s.error&&!s.data?errorBox(s.error):s.tab==='rsu'?rsuPanelV168(j):s.tab==='assets'?assetsPanelV168(j):s.tab==='pensions'?pensionsPanel(j):wealthOverviewV168(j);return '<div class="v168 v168-wealth">'+head('Patrimônio','Patrimônio','Dinheiro atual, posições futuras, recursos restritos, bens e dívidas.',sourceLabel(j.as_of||today()))+(s.loading&&s.data?'<div class="v168-loadstatus"><i></i><span><b>Posição preservada.</b> Atualizando detalhes…</span></div>':'')+wealthTabs()+body+'</div>'}

