    function bindUpdates(){const xs=filteredActions();document.querySelectorAll('[data-v168-action]').forEach(b=>b.onclick=()=>{const x=xs[Number(b.dataset.v168Action)];if(!x)return;if(isStatementAction(x))return openUpload(bankFromAction(x));if(x.origin==='recurring')return openProposal(x);st.search.query=x.card_name||x.title||'';runSearch(st.search.query)});const input=document.getElementById('v168SearchInput'),button=document.getElementById('v168SearchButton');if(input)input.oninput=()=>{st.search.query=input.value;clearTimeout(st.search.timer);st.search.timer=setTimeout(()=>runSearch(input.value),280)};if(button)button.onclick=()=>runSearch(input?.value||'');document.querySelectorAll('[data-v168-search-flow]').forEach(b=>b.onclick=()=>openInFlow(st.search.rows[Number(b.dataset.v168SearchFlow)],false));document.querySelectorAll('[data-v168-search-edit]').forEach(b=>b.onclick=()=>openInFlow(st.search.rows[Number(b.dataset.v168SearchEdit)],true));const phrase=document.getElementById('v168NlPhrase');if(phrase)phrase.oninput=()=>st.nl.draft=phrase.value;document.getElementById('v168NlPreview')?.addEventListener('click',()=>{st.nl.draft=phrase?.value||'';st.nl.error='';st.nl.message='';if(!st.nl.draft.trim())st.nl.error='Escreva o lançamento antes de interpretar.';else{st.nl.preview=parsePhrase(st.nl.draft);st.nl.key='v168-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}render()});const check=document.getElementById('v168NlConfirm'),apply=document.getElementById('v168NlApply');if(check&&apply)check.onchange=()=>apply.disabled=!check.checked||st.nl.busy;if(apply)apply.onclick=applyNatural}
    function decorateFlow(){if(V!=='Fluxo Diário')return;const foot=document.querySelector('.fv-foot');if(foot&&!foot.querySelector('.v168-history-note'))foot.insertAdjacentHTML('beforeend','<div class="v168-history-note" style="margin-top:5px"><b>Histórico:</b> antes da primeira abertura documental completa, o LTS mostra movimentos e deixa o saldo absoluto em branco — não projeta o saldo atual para trás.</div>')}
