  function frame(){try{const w=outer?.contentWindow,d=outer?.contentDocument;if(!w||!d||!String(w.location.pathname||'').endsWith('/index.html'))return null;return{w,d}}catch{return null}}
  function install(){const f=frame();if(!f)return false;const superseded=String(window.__LTS_TOP_CANDIDATE_VERSION||'').startsWith('v169');if(!superseded){f.d.querySelectorAll('.brand small').forEach(n=>n.innerHTML='<b>V168</b> · Homologação');if(scope)scope.textContent='V168 · Homologação'}if(!f.w.__LTS_V166_FEEDBACK?.installed)return false;if(!f.w.__LTS_V168_COMPLETE_REVIEW?.installed&&!f.d.getElementById('lts-v168-runtime')){const s=f.d.createElement('script');s.id='lts-v168-runtime';s.textContent='('+runtime.toString()+')();';(f.d.head||f.d.documentElement).appendChild(s)}const ready=f.w.__LTS_V168_COMPLETE_REVIEW?.installed===true;if(ready&&gate)gate.hidden=true;return ready}
